INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 40011, "もうすぐ、みなさまに\nお会いできるのですね。\n胸が高鳴ってしまいます……\n", 1, "リリ", 125801, 321, 2, 1, 1, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 40011, "初めまして、クリアです♪\nみなさんと一緒に冒険するの\nとっても楽しみにしてます", 2, "クリア", 126001, 322, 2, 1, 1, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 40011, "んーと。\nこれ、あげる。\nはい", 3, "プレシア", 126101, 323, 2, 1, 1, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 40011, "あらためまして……\n【アルターメイデン】の\nギルドマスター、リリと申します", 4, "リリ", 125801, 324, 2, 2, 1, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 40011, "こんにちは、お兄さん♪\n【アルターメイデン】の\nクリアです", 5, "クリア", 126001, 325, 2, 2, 1, 0);
INSERT INTO `v1_b075dd1e0090b3e307364ce4bf3210ef9ae7948b43081d7a8200160d46ecb597` VALUES (24001, 40011, "お兄。\nきてくれて、うれしい", 6, "プレシア", 126101, 326, 2, 2, 1, 0);
